public int[] lisWithParents(int[] nums) {
    int n = nums.length;
    int[] dp = new int[n], parent = new int[n];
    Arrays.fill(dp, 1);
    Arrays.fill(parent, -1);
    int bestEnd = 0;
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[j] < nums[i] && dp[j] + 1 > dp[i]) {
                dp[i] = dp[j] + 1;
                parent[i] = j;
            }
        }
        if (dp[i] > dp[bestEnd]) bestEnd = i;
    }
    while (bestEnd != -1) {
        collect(nums[bestEnd]);
        bestEnd = parent[bestEnd];
    }
